using EEMS.SharedKernel.Domain;
namespace EEMS.Modules.Results.Domain;
internal static class R{public static string T(string v,int m){var x=v?.Trim()??"";return x.Length is >0&&x.Length<=m?x:throw new ArgumentException("Invalid value.");}}
public sealed class SubmissionState:Entity<short>{private SubmissionState(){}private SubmissionState(short id,string code,string name,bool verified){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));Id=id;Code=R.T(code,40);Name=R.T(name,100);IsVerified=verified;IsActive=true;}public string Code{get;private set;}="";public string Name{get;private set;}="";public bool IsVerified{get;private set;}public bool IsActive{get;private set;}public static SubmissionState Create(short id,string code,string name,bool verified=false)=>new(id,code,name,verified);}
public sealed class ResultSubmission:Entity<Guid>{private ResultSubmission(){}private ResultSubmission(Guid id,Guid tenant,Guid election,Guid center,long position,Guid submitter,short state,string key,int total){if(tenant==Guid.Empty||election==Guid.Empty||center==Guid.Empty||position<=0||submitter==Guid.Empty)throw new ArgumentException("References required.");if(state<=0||total<0)throw new ArgumentOutOfRangeException(nameof(total));Id=id;TenantId=tenant;ElectionId=election;ElectionCenterId=center;PositionId=position;SubmittedByUserId=submitter;StateId=state;IdempotencyKey=R.T(key,100);DeclaredTotalVotes=total;CreatedAtUtc=DateTimeOffset.UtcNow;Version=1;}public Guid TenantId{get;private set;}public Guid ElectionId{get;private set;}public Guid ElectionCenterId{get;private set;}public long PositionId{get;private set;}public Guid SubmittedByUserId{get;private set;}public short StateId{get;private set;}public string IdempotencyKey{get;private set;}="";public int DeclaredTotalVotes{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public int Version{get;private set;}public static ResultSubmission Create(Guid t,Guid e,Guid c,long p,Guid u,short s,string k,int total)=>new(Guid.NewGuid(),t,e,c,p,u,s,k,total);public void MoveTo(short s){if(s<=0)throw new ArgumentOutOfRangeException(nameof(s));StateId=s;Version++;}}
public sealed class ResultDetail{private ResultDetail(){}private ResultDetail(Guid t,Guid s,Guid candidate,int votes){if(t==Guid.Empty||s==Guid.Empty||candidate==Guid.Empty)throw new ArgumentException("References required.");ArgumentOutOfRangeException.ThrowIfNegative(votes);TenantId=t;SubmissionId=s;CandidateElectionId=candidate;Votes=votes;}public Guid TenantId{get;private set;}public Guid SubmissionId{get;private set;}public Guid CandidateElectionId{get;private set;}public int Votes{get;private set;}public static ResultDetail Create(Guid t,Guid s,Guid c,int v)=>new(t,s,c,v);}
public sealed class ResultDocument:Entity<Guid>{private ResultDocument(){}private ResultDocument(Guid t,Guid s,Guid u,string key,string hash,string mime,long size){if(t==Guid.Empty||s==Guid.Empty||u==Guid.Empty||size<=0)throw new ArgumentException("Invalid document.");Id=Guid.NewGuid();TenantId=t;SubmissionId=s;UploadedByUserId=u;StorageKey=R.T(key,500);Sha256=R.T(hash,64);MimeType=R.T(mime,120);SizeBytes=size;UploadedAtUtc=DateTimeOffset.UtcNow;}public Guid TenantId{get;private set;}public Guid SubmissionId{get;private set;}public Guid UploadedByUserId{get;private set;}public string StorageKey{get;private set;}="";public string Sha256{get;private set;}="";public string MimeType{get;private set;}="";public long SizeBytes{get;private set;}public DateTimeOffset UploadedAtUtc{get;private set;}public static ResultDocument Create(Guid t,Guid s,Guid u,string k,string h,string m,long z)=>new(t,s,u,k,h,m,z);}
public sealed class ResultVerification:Entity<Guid>{private ResultVerification(){}private ResultVerification(Guid t,Guid s,Guid submitter,Guid verifier,short state,string note){if(submitter==verifier)throw new InvalidOperationException("Submitter cannot verify own result.");if(t==Guid.Empty||s==Guid.Empty||verifier==Guid.Empty||state<=0)throw new ArgumentException("Invalid verification.");Id=Guid.NewGuid();TenantId=t;SubmissionId=s;SubmitterUserId=submitter;VerifierUserId=verifier;ResultingStateId=state;Note=R.T(note,2000);VerifiedAtUtc=DateTimeOffset.UtcNow;}public Guid TenantId{get;private set;}public Guid SubmissionId{get;private set;}public Guid SubmitterUserId{get;private set;}public Guid VerifierUserId{get;private set;}public short ResultingStateId{get;private set;}public string Note{get;private set;}="";public DateTimeOffset VerifiedAtUtc{get;private set;}public static ResultVerification Record(Guid t,Guid s,Guid maker,Guid checker,short state,string note)=>new(t,s,maker,checker,state,note);}
public sealed class ResultDispute:Entity<Guid>{private ResultDispute(){}private ResultDispute(Guid t,Guid s,Guid u,string reason){if(t==Guid.Empty||s==Guid.Empty||u==Guid.Empty)throw new ArgumentException("Invalid dispute.");Id=Guid.NewGuid();TenantId=t;SubmissionId=s;RaisedByUserId=u;Reason=R.T(reason,3000);RaisedAtUtc=DateTimeOffset.UtcNow;}public Guid TenantId{get;private set;}public Guid SubmissionId{get;private set;}public Guid RaisedByUserId{get;private set;}public string Reason{get;private set;}="";public DateTimeOffset RaisedAtUtc{get;private set;}public static ResultDispute Raise(Guid t,Guid s,Guid u,string r)=>new(t,s,u,r);}
public sealed class OfficialResult:Entity<Guid>{private OfficialResult(){}private OfficialResult(Guid t,Guid e,long p,Guid candidate,long votes,string source,Guid publisher){if(t==Guid.Empty||e==Guid.Empty||p<=0||candidate==Guid.Empty||publisher==Guid.Empty||votes<0)throw new ArgumentException("Invalid official result.");Id=Guid.NewGuid();TenantId=t;ElectionId=e;PositionId=p;CandidateElectionId=candidate;Votes=votes;AuthoritySource=R.T(source,300);PublishedByUserId=publisher;PublishedAtUtc=DateTimeOffset.UtcNow;}public Guid TenantId{get;private set;}public Guid ElectionId{get;private set;}public long PositionId{get;private set;}public Guid CandidateElectionId{get;private set;}public long Votes{get;private set;}public string AuthoritySource{get;private set;}="";public Guid PublishedByUserId{get;private set;}public DateTimeOffset PublishedAtUtc{get;private set;}public static OfficialResult Publish(Guid t,Guid e,long p,Guid c,long v,string s,Guid u)=>new(t,e,p,c,v,s,u);}
